import torch.nn as nn
from torch.utils.cpp_extension import load_inline
import torch

matmul_cuda_source = """
#include <torch/extension.h>
#include <cuda_runtime.h>

__global__ void matmul_kernel(const float* A, const float* B, float* C, int N) {
    int globalRow = blockIdx.y * blockDim.y + threadIdx.y;
    int globalCol = blockIdx.x * blockDim.x + threadIdx.x;

    if (globalRow < N && globalCol < N) {
        float C_value = 0.0f;
        for (int k = 0; k < N; ++k) {
            C_value += A[globalRow * N + k] * B[k * N + globalCol];
        }
        C[globalRow * N + globalCol] = C_value;
    }
}

torch::Tensor matmul_cuda(torch::Tensor A, torch::Tensor B) {
    // Ensure inputs are contiguous
    A = A.contiguous();
    B = B.contiguous();

    int N = A.size(0); // Assuming square matrices N x N

    auto C = torch::zeros({N, N}, A.options());

    // Define block and grid dimensions
    const int BLOCK_SIZE = 32; // Standard block size for 2D kernels
    dim3 blocks_per_grid((N + BLOCK_SIZE - 1) / BLOCK_SIZE, (N + BLOCK_SIZE - 1) / BLOCK_SIZE);
    dim3 threads_per_block(BLOCK_SIZE, BLOCK_SIZE);

    matmul_kernel<<<blocks_per_grid, threads_per_block>>>(
        A.data_ptr<float>(), B.data_ptr<float>(), C.data_ptr<float>(), N
    );

    return C;
}
"""

matmul_cpp_source = (
    "torch::Tensor matmul_cuda(torch::Tensor A, torch::Tensor B);"
)

